            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "atributos concretos que le afirmaste a ESTE producto (medida, faz, material, color, acabado). Cada uno tiene que salir de la MISMA opción [vN] de Opciones, o de lo común del producto (nombre, Sirve para, Material/Tecnología)"
          },
          "cantidad": {
            "type": [
              "number",
              "null"
            ],
            "description": "cantidad que el cliente pidió para este producto, si la mencionó; sino null"
